on conflict (id) do update set nombre = excluded.nombre, subtitulo = excluded.subtitulo, orden = excluded.orden;

on conflict (id) do update set grupo_id = excluded.grupo_id, nombre = excluded.nombre, imagen_url = excluded.imagen_url, numero = excluded.numero;

-- Mantiene el contador de ids en orden por si después agregas personajes a mano.
select setval(pg_get_serial_sequence('public.personajes', 'id'), (select max(id) from public.personajes));
